static int telinit_help ( void ) { int r ; r = terminal_urlify_man ( "telinit" , "8" , & link ) ; if ( r < 0 ) { return log_oom ( ) ; } printf ( "%s [OPTIONS...] COMMAND\n\n" "%sSend control commands to the init daemon.%s\n" "\nCommands:\n" "  0              Power-off the machine\n" "  6              Reboot the machine\n" "  2, 3, 4, 5     Start runlevelX.target unit\n" "  1, s, S        Enter rescue mode\n" "  q, Q           Reload init daemon configuration\n" "  u, U           Reexecute init daemon\n" "\nOptions:\n" "     --help      Show this help\n" "     --no-wall   Don't send wall message before halt/power-off/reboot\n" "\nSee the %s for details.\n" , program_invocation_short_name , ansi_highlight ( ) , ansi_normal ( ) , link ) ; return 0 ; } 